import{_ as e,o as n,c as o,a5 as d}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"07 — Kết nối Mạng xã hội, Lên lịch & Xuất bản Đa Nền tảng (Publishing & Social Integration)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/07-publishing-social-collaborator.md","filePath":"ba/07-publishing-social-collaborator.md"}'),c={name:"ba/07-publishing-social-collaborator.md"};function a(i,t,l,r,g,s){return n(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="_07-—-ket-noi-mang-xa-hoi-len-lich-xuat-ban-đa-nen-tang-publishing-social-integration" tabindex="-1">07 — Kết nối Mạng xã hội, Lên lịch &amp; Xuất bản Đa Nền tảng (Publishing &amp; Social Integration) <a class="header-anchor" href="#_07-—-ket-noi-mang-xa-hoi-len-lich-xuat-ban-đa-nen-tang-publishing-social-integration" aria-label="Permalink to &quot;07 — Kết nối Mạng xã hội, Lên lịch &amp; Xuất bản Đa Nền tảng (Publishing &amp; Social Integration)&quot;">​</a></h1><p>&gt; [&lt;&lt; 06 - AI Features](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/06-ai-features.md) | [Overview](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/00-overview.md) | [Tiếp: 08 - Subscription &amp; Billing &gt;&gt;](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/08-subscription-billing.md) &gt; &gt; <strong>Phạm vi FR chuẩn</strong>: <strong>Mục <code>3.8 Publishing &amp; Social</code> — 15 FR (<code>3.8.1</code> – <code>3.8.15</code>)</strong> | <code>UC-107</code> – <code>UC-121</code>. &gt; Tuân thủ nghiêm ngặt quy tắc <strong>4 nền tảng mạng xã hội chuẩn: Facebook, Instagram, TikTok, và Threads</strong> (không có Zalo OA theo <code>AGENTS.md</code>). &gt; <em>(Lưu ý: Nhóm Danh bạ Cộng tác viên / KOL Directory đã được chuẩn hóa sang mục <code>3.7.15</code>–<code>3.7.19</code> trong [06-ai-features.md](file:///D:/ProjectCode/BrandHub/brandhub-infrastructure/docs/ba/06-ai-features.md)).</em></p><hr><h2 id="_1-bang-tong-hop-15-yeu-cau-chuc-nang-chuan-3-8-1-–-3-8-15" tabindex="-1">1. Bảng Tổng hợp 15 Yêu cầu Chức năng Chuẩn (<code>3.8.1</code> – <code>3.8.15</code>) <a class="header-anchor" href="#_1-bang-tong-hop-15-yeu-cau-chuc-nang-chuan-3-8-1-–-3-8-15" aria-label="Permalink to &quot;1. Bảng Tổng hợp 15 Yêu cầu Chức năng Chuẩn (`3.8.1` – `3.8.15`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (Atomic CRUD FR)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.8.1</code></strong></td><td style="text-align:center;"><code>UC-107</code></td><td style="text-align:left;"><strong>Connect Social Account</strong></td><td style="text-align:left;"><code>Client</code>, <code>Manager</code> <em>(và <code>Owner</code> ở chế độ <code>PERSONAL</code>)</em></td><td style="text-align:left;">Kết nối tài khoản mạng xã hội chính chủ (Facebook Page, Instagram Business, TikTok Account, Threads Profile) vào Workspace qua giao thức OAuth 2.0.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.2</code></strong></td><td style="text-align:center;"><code>UC-108</code></td><td style="text-align:left;"><strong>Disconnect Account</strong></td><td style="text-align:left;"><code>Client</code>, <code>Manager</code> <em>(và <code>Owner</code> ở chế độ <code>PERSONAL</code>)</em></td><td style="text-align:left;">Ngắt kết nối một tài khoản mạng xã hội khỏi Workspace; thu hồi token lưu trữ và dừng các lịch đăng tự động gắn với tài khoản đó.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.3</code></strong></td><td style="text-align:center;"><code>UC-109</code></td><td style="text-align:left;"><strong>View Dashboard Post</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem bảng tổng hợp hiệu quả và danh sách các bài đã đăng trên các kênh mạng xã hội của Workspace (lượt tiếp cận, tương tác, bình luận tổng hợp).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.4</code></strong></td><td style="text-align:center;"><code>UC-110</code></td><td style="text-align:left;"><strong>View Posted Detail</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem chi tiết một bài viết đã xuất bản kèm đường dẫn trực tiếp tới bài đăng gốc trên từng nền tảng và các chỉ số tương tác chi tiết.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.5</code></strong></td><td style="text-align:center;"><code>UC-111</code></td><td style="text-align:left;"><strong>Preview Post</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Xem trước giao diện hiển thị của bài viết (<code>Mockup Preview</code> chuẩn xác theo khung giao diện của Facebook, Instagram, TikTok, Threads trên cả Mobile &amp; Desktop) trước khi duyệt hoặc xuất bản.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.6</code></strong></td><td style="text-align:center;"><code>UC-112</code></td><td style="text-align:left;"><strong>Schedule Platform Post</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Thiết lập thời điểm xuất bản tự động (<code>scheduledAt</code>) và chọn danh sách nền tảng mục tiêu (<code>targetPlatforms</code>) trong phần <code>POST.CHANNELS</code> / <code>VIDEO.CHANNELS</code>.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.7</code></strong></td><td style="text-align:center;"><code>UC-113</code></td><td style="text-align:left;"><strong>Track Post Status</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:left;">Theo dõi trạng thái xuất bản thời gian thực của từng nền tảng (<code>SCHEDULED</code> → <code>PUBLISHING</code> → <code>PUBLISHED</code> / <code>PARTIALLY_PUBLISHED</code> / <code>FAILED</code>) kèm thông báo lỗi chi tiết và nút thử đăng lại (<code>Retry</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.8</code></strong></td><td style="text-align:center;"><code>UC-114</code></td><td style="text-align:left;"><strong>Publish Facebook Post</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản bài viết thường (văn bản, bộ ảnh hoặc video) lên Facebook Page qua Meta Graph API.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.9</code></strong></td><td style="text-align:center;"><code>UC-115</code></td><td style="text-align:left;"><strong>Publish Facebook Reels</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản video ngắn dọc (<code>9:16</code>) lên mục Facebook Reels của Fanpage.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.10</code></strong></td><td style="text-align:center;"><code>UC-116</code></td><td style="text-align:left;"><strong>Publish Facebook Stories</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản tin ngắn 24 giờ (ảnh hoặc video dọc) lên Facebook Page Stories.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.11</code></strong></td><td style="text-align:center;"><code>UC-117</code></td><td style="text-align:left;"><strong>Publish Instagram Post</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản bài đăng ảnh đơn, album轮播 (Carousel) hoặc video lên tài khoản Instagram Business/Creator.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.12</code></strong></td><td style="text-align:center;"><code>UC-118</code></td><td style="text-align:left;"><strong>Publish Instagram Reels</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản video ngắn dọc lên Instagram Reels kèm ảnh bìa (<code>cover</code>) và caption.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.13</code></strong></td><td style="text-align:center;"><code>UC-119</code></td><td style="text-align:left;"><strong>Publish Instagram Stories</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản ảnh/video lên Instagram Stories.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.14</code></strong></td><td style="text-align:center;"><code>UC-120</code></td><td style="text-align:left;"><strong>Publish TikTok Video</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản video ngắn lên kênh TikTok qua TikTok Content Posting API (kèm tùy chọn quyền riêng tư và cho phép bình luận/duet/stitch).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.15</code></strong></td><td style="text-align:center;"><code>UC-121</code></td><td style="text-align:left;"><strong>Publish Threads Post</strong></td><td style="text-align:left;"><code>Manager</code>, <code>Creator</code></td><td style="text-align:left;">Xuất bản bài viết văn bản, hình ảnh hoặc video ngắn lên nền tảng Meta Threads qua Threads API.</td></tr></tbody></table><hr><h2 id="_2-đac-ta-nghiep-vu-ket-noi-tai-khoan-mang-xa-hoi-3-8-1-–-3-8-2" tabindex="-1">2. Đặc tả Nghiệp vụ Kết nối Tài khoản Mạng xã hội (<code>3.8.1</code> – <code>3.8.2</code>) <a class="header-anchor" href="#_2-đac-ta-nghiep-vu-ket-noi-tai-khoan-mang-xa-hoi-3-8-1-–-3-8-2" aria-label="Permalink to &quot;2. Đặc tả Nghiệp vụ Kết nối Tài khoản Mạng xã hội (`3.8.1` – `3.8.2`)&quot;">​</a></h2><h3 id="_2-1-quyen-ket-noi-trong-che-đo-agency-vs-personal" tabindex="-1">2.1. Quyền Kết nối trong Chế độ <code>AGENCY</code> vs. <code>PERSONAL</code> <a class="header-anchor" href="#_2-1-quyen-ket-noi-trong-che-đo-agency-vs-personal" aria-label="Permalink to &quot;2.1. Quyền Kết nối trong Chế độ `AGENCY` vs. `PERSONAL`&quot;">​</a></h3><ul><li><strong>Trong Chế độ <code>AGENCY</code> (<code>workspaceMode = &quot;AGENCY&quot;</code>)</strong>: <ul><li>Cả <strong><code>Client</code></strong> (tại <code>Client Portal</code> hoặc trang kết nối) và <strong><code>Manager</code></strong> (cùng <code>Owner</code>) đều có quyền thực hiện OAuth kết nối tài khoản MXH của thương hiệu vào Workspace.</li></ul></li><li><strong>Trong Chế độ <code>PERSONAL</code> (<code>workspaceMode = &quot;PERSONAL&quot;</code>)</strong>: <ul><li>Chủ không gian (<strong><code>Owner</code> / <code>Manager</code></strong>) kết nối trực tiếp các kênh Facebook, Instagram, TikTok, Threads cá nhân của mình tại <code>/workspaces/:id/social-accounts</code> (hoặc bấm từ <strong>Bệ phóng Sáng tạo Cá nhân — Personal Quick Launchpad</strong> trên Dashboard) mà không cần thông qua bất kỳ tài khoản <code>Client</code> nào.</li></ul></li></ul><h3 id="_2-2-quan-ly-vong-đoi-token-oauth" tabindex="-1">2.2. Quản lý Vòng đời Token OAuth <a class="header-anchor" href="#_2-2-quan-ly-vong-đoi-token-oauth" aria-label="Permalink to &quot;2.2. Quản lý Vòng đời Token OAuth&quot;">​</a></h3><ul><li>Mọi <code>accessToken</code> và <code>refreshToken</code> của 4 nền tảng được mã hóa an toàn trước khi lưu trữ và được quản lý bởi <code>brandhub-publisher-service</code> / <code>brandhub-business-service</code>.</li><li>Khi token sắp hết hạn, dịch vụ tự động gia hạn ngầm (<code>Token Refresh</code>); nếu người dùng đổi mật khẩu MXH hoặc thu hồi quyền từ phía nền tảng khiến token hết hiệu lực (<code>EXPIRED</code>), hệ thống hiển thị cảnh báo trạng thái cần kết nối lại (<code>Reconnect</code>).</li></ul><hr><h2 id="_3-quy-trinh-len-lich-phe-duyet-xuat-ban-đa-nen-tang-3-8-5-–-3-8-15" tabindex="-1">3. Quy trình Lên lịch, Phê duyệt &amp; Xuất bản Đa Nền tảng (<code>3.8.5</code> – <code>3.8.15</code>) <a class="header-anchor" href="#_3-quy-trinh-len-lich-phe-duyet-xuat-ban-đa-nen-tang-3-8-5-–-3-8-15" aria-label="Permalink to &quot;3. Quy trình Lên lịch, Phê duyệt &amp; Xuất bản Đa Nền tảng (`3.8.5` – `3.8.15`)&quot;">​</a></h2><h3 id="_3-1-đieu-kien-tien-quyet-đe-xuat-ban-publishing-gate" tabindex="-1">3.1. Điều kiện Tiên quyết Để Xuất bản (<code>Publishing Gate</code>) <a class="header-anchor" href="#_3-1-đieu-kien-tien-quyet-đe-xuat-ban-publishing-gate" aria-label="Permalink to &quot;3.1. Điều kiện Tiên quyết Để Xuất bản (`Publishing Gate`)&quot;">​</a></h3><p>Để đảm bảo không bao giờ đăng nhầm nội dung chưa được phê duyệt lên mạng xã hội:</p><ol><li><strong>Quyền cấu hình kênh &amp; lịch đăng (<code>POST.CHANNELS</code> / <code>VIDEO.CHANNELS</code>)</strong>: <ul><li>Người giữ vai trò <code>POST_PUBLISHING</code> (với Task <code>POST</code>), <code>VIDEO_PUBLISH</code> (với Task <code>SHORT_VIDEO</code>), Điều phối viên (<code>assigneeId</code>), hoặc <code>Manager</code> / <code>Owner</code> có thể chọn kênh xuất bản và đặt giờ đăng dự kiến (<code>scheduledAt</code>) bất cứ lúc nào khi phần còn mở.</li><li>Riêng công việc loại <code>SHORT_VIDEO</code> chỉ cho phép chọn các kênh hỗ trợ định dạng video ngắn: <strong>TikTok (<code>3.8.14</code>), Instagram Reels (<code>3.8.12</code>), Facebook Reels (<code>3.8.9</code>)</strong>.</li></ul></li><li><strong>Điều kiện mở khóa Xuất bản thật (<code>Publish Now</code> &amp; <code>PostSchedulePublishJob</code>)</strong>: <ul><li>Lệnh xuất bản thật sang <code>brandhub-publisher-service</code> (qua hàng đợi RabbitMQ <code>PublishJobMessage</code>) <strong>chỉ được kích hoạt khi Công việc cha đã hoàn tất phê duyệt</strong>: <ul><li><code>task.status == TaskStatus.FINISHED</code> <strong>VÀ</strong> <code>task.lastSubmission.outcome == ApprovalOutcome.APPROVED</code>.</li></ul></li><li><strong>Ở chế độ <code>AGENCY</code></strong>: Đạt được sau khi <code>Manager</code> duyệt nội bộ và <code>Client</code> duyệt đủ các phần sản phẩm đầu ra (<code>CLIENT_APPROVED</code>).</li><li><strong>Ở chế độ <code>PERSONAL</code></strong>: Đạt được <strong>ngay lập tức chỉ với 1 cú nhấp chuột</strong> khi chủ không gian bấm nút <strong>&quot;Hoàn tất &amp; Duyệt ngay (<code>Self-Approve</code>)&quot;</strong> (<code>POST /api/v1/workspaces/{id}/tasks/{taskId}/self-approve</code>).</li></ul></li></ol><h3 id="_3-2-co-che-huy-lich-tu-đong-khi-noi-dung-bi-tra-lai" tabindex="-1">3.2. Cơ chế Hủy lịch Tự động Khi Nội dung Bị Trả lại <a class="header-anchor" href="#_3-2-co-che-huy-lich-tu-đong-khi-noi-dung-bi-tra-lai" aria-label="Permalink to &quot;3.2. Cơ chế Hủy lịch Tự động Khi Nội dung Bị Trả lại&quot;">​</a></h3><ul><li>Nếu một bài viết đã được đặt lịch (<code>status = SCHEDULED</code>), nhưng trước giờ đăng mà <code>Client</code> hoặc <code>Manager</code> bấm <strong>Trả lại (<code>Return</code>)</strong> một phần nội dung để yêu cầu chỉnh sửa: <ul><li>Hệ thống tự động đưa Task cha về <code>IN_PROGRESS</code> và gọi <code>PostService.cancelTaskSchedule(workspaceId, taskId)</code> để chuyển bài viết về <code>DRAFT</code>, xóa <code>scheduledAt</code>.</li><li>Nhờ đó, <code>PostSchedulePublishJob</code> (quét định kỳ mỗi 30 giây) sẽ tự động bỏ qua bài viết đó cho đến khi nội dung được sửa, duyệt lại và đặt lịch mới.</li></ul></li></ul><h3 id="_3-3-quy-chuan-ky-thuat-theo-tung-đinh-dang-xuat-ban-3-8-8-–-3-8-15" tabindex="-1">3.3. Quy chuẩn Kỹ thuật Theo Từng Định dạng Xuất bản (<code>3.8.8</code> – <code>3.8.15</code>) <a class="header-anchor" href="#_3-3-quy-chuan-ky-thuat-theo-tung-đinh-dang-xuat-ban-3-8-8-–-3-8-15" aria-label="Permalink to &quot;3.3. Quy chuẩn Kỹ thuật Theo Từng Định dạng Xuất bản (`3.8.8` – `3.8.15`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:left;">Định dạng Xuất bản</th><th style="text-align:center;">Nền tảng</th><th style="text-align:left;">Yêu cầu Nội dung &amp; Media Đầu vào</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.8.8</code></strong></td><td style="text-align:left;"><strong>Facebook Post</strong></td><td style="text-align:center;">Facebook Page</td><td style="text-align:left;">Văn bản (<code>caption</code> ≤ 63.206 ký tự), kèm tùy chọn 1–10 ảnh (JPG/PNG/WebP) hoặc 1 video.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.9</code></strong></td><td style="text-align:left;"><strong>Facebook Reels</strong></td><td style="text-align:center;">Facebook Page</td><td style="text-align:left;">Bắt buộc 1 video dọc (<code>9:16</code> khuyến nghị, thời lượng 3s–90s, MP4/MOV) + mô tả ngắn.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.10</code></strong></td><td style="text-align:left;"><strong>Facebook Stories</strong></td><td style="text-align:center;">Facebook Page</td><td style="text-align:left;">Bắt buộc 1 ảnh hoặc 1 video ngắn dọc hiển thị trong 24 giờ.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.11</code></strong></td><td style="text-align:left;"><strong>Instagram Post</strong></td><td style="text-align:center;">Instagram Business</td><td style="text-align:left;">Bắt buộc ít nhất 1 ảnh hoặc album Carousel (tối đa 10 media) + <code>caption</code> (≤ 2.200 ký tự, tối đa 30 hashtag).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.12</code></strong></td><td style="text-align:left;"><strong>Instagram Reels</strong></td><td style="text-align:center;">Instagram Business</td><td style="text-align:left;">Bắt buộc 1 video dọc (MP4/MOV, tối đa 15 phút, khuyến nghị ≤ 90s) + <code>caption</code> + ảnh bìa tùy chọn.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.13</code></strong></td><td style="text-align:left;"><strong>Instagram Stories</strong></td><td style="text-align:center;">Instagram Business</td><td style="text-align:left;">Bắt buộc 1 ảnh hoặc 1 video ngắn dọc hiển thị trong 24 giờ.</td></tr><tr><td style="text-align:center;"><strong><code>3.8.14</code></strong></td><td style="text-align:left;"><strong>TikTok Video</strong></td><td style="text-align:center;">TikTok</td><td style="text-align:left;">Bắt buộc 1 video (MP4/WebM/MOV, 3s–10 phút) + tiêu đề/caption (≤ 2.200 ký tự).</td></tr><tr><td style="text-align:center;"><strong><code>3.8.15</code></strong></td><td style="text-align:left;"><strong>Threads Post</strong></td><td style="text-align:center;">Threads</td><td style="text-align:left;">Văn bản (≤ 500 ký tự mỗi bài) và/hoặc ảnh/video đính kèm.</td></tr></tbody></table>',20)])])}const b=e(c,[["render",a]]);export{u as __pageData,b as default};
